// Per occupied voxel: 0 = cube; 1–4 = a wedge rising toward N/E/S/W.
export const BLOCK_GEOMETRY_SIZE=2400;
export function validateBlockGeometry(value,voxels){if(typeof value!=='string'||value.length!==BLOCK_GEOMETRY_SIZE||/[^0-4]/.test(value)||!voxels)throw Error('Block geometry needs 2,400 cube or wedge entries on an independent-layer building.');for(let i=0;i<2400;i++)if(value[i]!=='0'&&!(voxels[i%100]&(1<<Math.floor(i/100))))throw Error('A shaped block must occupy its layer.');return value;}
export function blockCornerHeights(shape){return shape===1?[1,1,0,0]:shape===2?[0,1,1,0]:shape===3?[0,0,1,1]:shape===4?[1,0,0,1]:[1,1,1,1];}
export function setBlockGeometry(geometry,points,shape,voxels){if(!Number.isInteger(shape)||shape<0||shape>4)throw Error('Choose a cube or wedge orientation.');const out=(geometry||'0'.repeat(2400)).split('');for(const {x,y,z} of points){if(![x,y,z].every(Number.isInteger)||x<0||x>=10||y<0||y>=10||z<0||z>=24)throw Error('Choose a block inside the building.');out[z*100+y*10+x]=String(shape);}for(let i=0;i<2400;i++)if(!(voxels[i%100]&(1<<Math.floor(i/100))))out[i]='0';const result=out.join('');return result.includes('1')||result.includes('2')||result.includes('3')||result.includes('4')?result:undefined;}
